sp_widget.client_script:
api.controller = function() {

    var c = this;


    /*
     * =========================================
     * FILTER VARIABLES
     * =========================================
     */

    c.searchText = "";

    c.statusFilter = "all";


    /*
     * =========================================
     * FILTER REQUESTS
     * =========================================
     */

    c.filteredRequests = function() {

        var results = [];

        var requests =
            c.data.requests || [];


        var search =
            (c.searchText || "")
                .toLowerCase();


        var filter =
            c.statusFilter || "all";


        angular.forEach(
            requests,
            function(request) {


                /*
                 * SEARCH
                 */

                var matchesSearch = true;


                if (search) {

                    var text =
                        (
                            request.number +
                            " " +
                            request.short_description +
                            " " +
                            request.state +
                            " " +
                            request.priority +
                            " " +
                            request.mealType +
                            " " +
                            request.messHall
                        ).toLowerCase();


                    matchesSearch =
                        text.indexOf(search) !== -1;

                }


                /*
                 * STATUS FILTER
                 */

                var matchesStatus = true;


                if (filter == "active") {

                    matchesStatus =
                        request.stateValue != "6" &&
                        request.stateValue != "7";

                }

                else if (filter == "resolved") {

                    matchesStatus =
                        request.stateValue == "6" ||
                        request.stateValue == "7";

                }


                /*
                 * ADD RESULT
                 */

                if (matchesSearch &&
                    matchesStatus) {

                    results.push(request);

                }

            }
        );


        return results;

    };


    /*
     * =========================================
     * BACK TO DASHBOARD
     * =========================================
     */

    c.backToDashboard = function() {

        window.location.href =
            "?id=cfms_student";

    };


    /*
     * =========================================
     * RAISE NEW REQUEST
     * =========================================
     */

    c.raiseRequest = function() {

        window.location.href =
            "?id=cfms_raise";

    };


    /*
     * =========================================
     * VIEW REQUEST
     * =========================================
     */

    c.viewRequest = function(request) {

        /*
         * For now, open the ServiceNow
         * incident form.
         */

        if (request &&
            request.sys_id) {

            window.location.href =
                "?id=cfms_request_detail" +
                "&sys_id=" +
                encodeURIComponent(
                    request.sys_id
                );

        }

    };

};

sp_widget.css:
/* =========================================
   CFMS MY REQUESTS
   ========================================= */

.cfms-my-requests {
    min-height: 100vh;

    background: #f0fbfc;

    color: #263238;

    font-family:
        "Segoe UI",
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;

    padding-bottom: 50px;
}


/* =========================================
   HEADER
   ========================================= */

.requests-header {
    min-height: 105px;

    background: #00acc1;

    color: white;

    padding: 25px 7%;

    box-sizing: border-box;

    display: flex;

    align-items: center;

    justify-content: space-between;
}


.header-left {
    display: flex;

    align-items: center;

    gap: 18px;
}


.back-btn {
    width: 42px;
    height: 42px;

    border: 1px solid rgba(255,255,255,0.7);

    border-radius: 8px;

    background: transparent;

    color: white;

    cursor: pointer;
}


.back-btn:hover {
    background: white;

    color: #00acc1;
}


.header-left h1 {
    margin: 0 0 5px;

    font-size: 29px;
}


.header-left p {
    margin: 0;

    font-size: 13px;

    opacity: 0.9;
}


.new-request-btn {
    padding: 11px 18px;

    border: none;

    border-radius: 7px;

    background: white;

    color: #00acc1;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;
}


.new-request-btn:hover {
    background: #e0f7fa;
}


/* =========================================
   CONTAINER
   ========================================= */

.requests-container {
    max-width: 1100px;

    margin: 35px auto;

    padding: 0 25px;

    box-sizing: border-box;
}


/* =========================================
   SUMMARY
   ========================================= */

.summary-grid {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 18px;

    margin-bottom: 25px;
}


.summary-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 12px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    box-shadow:
        0 4px 15px rgba(0,0,0,0.05);
}


.summary-icon {
    width: 48px;
    height: 48px;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;
}


.summary-icon.teal {
    background: #e0f7fa;

    color: #00acc1;
}


.summary-icon.blue {
    background: #e3f2fd;

    color: #1976d2;
}


.summary-icon.green {
    background: #e8f5e9;

    color: #43a047;
}


.summary-card span {
    display: block;

    color: #78909c;

    font-size: 12px;

    margin-bottom: 4px;
}


.summary-card strong {
    color: #263238;

    font-size: 24px;
}


/* =========================================
   FILTER
   ========================================= */

.filter-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 12px;

    padding: 15px;

    margin-bottom: 20px;

    display: flex;

    gap: 15px;
}


.search-box {
    flex: 1;

    position: relative;
}


.search-box i {
    position: absolute;

    left: 13px;

    top: 13px;

    color: #90a4ae;
}


.search-box input {
    width: 100%;

    height: 42px;

    box-sizing: border-box;

    padding: 8px 12px 8px 38px;

    border: 1px solid #d5e4e6;

    border-radius: 7px;

    outline: none;

    font-family: inherit;
}


.search-box input:focus {
    border-color: #00acc1;

    box-shadow:
        0 0 0 3px rgba(0,172,193,0.08);
}


.status-filter {
    width: 180px;

    height: 42px;

    padding: 8px 12px;

    border: 1px solid #d5e4e6;

    border-radius: 7px;

    background: white;

    color: #37474f;

    outline: none;

    cursor: pointer;
}


/* =========================================
   REQUESTS CARD
   ========================================= */

.requests-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 13px;

    overflow: hidden;

    box-shadow:
        0 4px 15px rgba(0,0,0,0.04);
}


.requests-card-header {
    padding: 22px 25px;

    border-bottom: 1px solid #edf3f4;

    display: flex;

    align-items: center;

    justify-content: space-between;
}


.requests-card-header h2 {
    margin: 0 0 4px;

    font-size: 20px;
}


.requests-card-header p {
    margin: 0;

    color: #78909c;

    font-size: 12px;
}


.request-count {
    color: #00acc1;

    background: #e0f7fa;

    padding: 7px 11px;

    border-radius: 20px;

    font-size: 11px;

    font-weight: 600;
}


/* =========================================
   REQUEST ITEM
   ========================================= */

.request-item {
    min-height: 90px;

    padding: 18px 22px;

    display: flex;

    align-items: center;

    gap: 16px;

    border-bottom: 1px solid #edf3f4;

    transition: 0.2s ease;
}


.request-item:last-child {
    border-bottom: none;
}


.request-item:hover {
    background: #fbfefe;
}


/* =========================================
   REQUEST ICON
   ========================================= */

.request-type-icon {
    width: 46px;
    height: 46px;

    flex-shrink: 0;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 19px;
}


.request-type-icon.teal {
    background: #e0f7fa;

    color: #00acc1;
}


.request-type-icon.orange {
    background: #fff3e0;

    color: #fb8c00;
}


.request-type-icon.red {
    background: #ffebee;

    color: #e53935;
}


/* =========================================
   INFORMATION
   ========================================= */

.request-information {
    flex: 1;

    min-width: 0;
}


.request-title-row {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 5px;
}


.request-title-row h3 {
    margin: 0;

    font-size: 14px;

    color: #00acc1;
}


.request-information h4 {
    margin: 0 0 9px;

    color: #37474f;

    font-size: 14px;

    font-weight: 600;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.request-meta {
    display: flex;

    gap: 17px;

    flex-wrap: wrap;
}


.request-meta span {
    color: #90a4ae;

    font-size: 11px;
}


.request-meta i {
    margin-right: 4px;

    color: #00acc1;
}


/* =========================================
   STATUS
   ========================================= */

.status-badge {
    padding: 5px 9px;

    border-radius: 20px;

    font-size: 10px;

    font-weight: 600;
}


.status-active {
    background: #fff8e1;

    color: #f57f17;
}


.status-resolved {
    background: #e8f5e9;

    color: #2e7d32;
}


/* =========================================
   PRIORITY
   ========================================= */

.priority-section {
    min-width: 80px;

    display: flex;

    flex-direction: column;

    align-items: center;

    gap: 5px;
}


.priority-label {
    color: #90a4ae;

    font-size: 10px;
}


.priority-badge {
    padding: 5px 9px;

    border-radius: 15px;

    font-size: 10px;

    font-weight: 600;
}


.priority-critical {
    background: #ffebee;

    color: #c62828;
}


.priority-high {
    background: #fff3e0;

    color: #ef6c00;
}


.priority-medium {
    background: #fff8e1;

    color: #f9a825;
}


.priority-low {
    background: #e8f5e9;

    color: #388e3c;
}


/* =========================================
   VIEW BUTTON
   ========================================= */

.view-btn {
    padding: 8px 12px;

    border: 1px solid #b2ebf2;

    border-radius: 6px;

    background: white;

    color: #00acc1;

    font-size: 11px;

    font-weight: 600;

    cursor: pointer;
}


.view-btn:hover {
    background: #e0f7fa;
}


/* =========================================
   EMPTY
   ========================================= */

.empty-state {
    padding: 60px 20px;

    text-align: center;
}


.empty-icon {
    width: 65px;
    height: 65px;

    margin: 0 auto 15px;

    border-radius: 50%;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 27px;
}


.empty-state h3 {
    margin: 0 0 7px;

    font-size: 18px;
}


.empty-state p {
    color: #78909c;

    font-size: 13px;
}


.raise-empty-btn {
    margin-top: 10px;

    padding: 10px 18px;

    border: none;

    border-radius: 7px;

    background: #00acc1;

    color: white;

    font-weight: 600;

    cursor: pointer;
}


/* =========================================
   TRACKING INFO
   ========================================= */

.tracking-info {
    margin-top: 20px;

    padding: 18px 20px;

    display: flex;

    align-items: center;

    gap: 15px;

    border-radius: 11px;

    background: #4dd0e1;
}


.tracking-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.tracking-info h3 {
    margin: 0 0 4px;

    font-size: 15px;
}


.tracking-info p {
    margin: 0;

    color: #37474f;

    font-size: 12px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 800px) {

    .summary-grid {
        grid-template-columns: 1fr;
    }

    .request-item {
        flex-wrap: wrap;
    }

    .priority-section {
        display: none;
    }

}


@media (max-width: 600px) {

    .requests-header {
        padding: 22px 20px;

        flex-direction: column;

        align-items: flex-start;

        gap: 15px;
    }

    .new-request-btn {
        width: 100%;
    }

    .requests-container {
        padding: 0 15px;

        margin-top: 20px;
    }

    .filter-card {
        flex-direction: column;
    }

    .status-filter {
        width: 100%;
    }

    .requests-card-header {
        padding: 18px;
    }

    .request-item {
        padding: 16px;
    }

    .view-btn {
        width: 100%;
    }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * DEFAULT DATA
     * =========================================
     */

    data.requests = [];

    data.total = 0;

    data.active = 0;

    data.resolved = 0;

    data.error = "";


    /*
     * =========================================
     * LOGIN CHECK
     * =========================================
     */

    if (!gs.isLoggedIn()) {

        data.error =
            "Please login to view your requests.";

        return;
    }


    /*
     * =========================================
     * ROLE CHECK
     * =========================================
     */

    if (!gs.hasRole("cfms_student") &&
        !gs.hasRole("admin")) {

        data.error =
            "You are not authorized to view these requests.";

        return;
    }


    /*
     * =========================================
     * GET STUDENT REQUESTS
     * =========================================
     */

    var gr =
        new GlideRecord("incident");


    /*
     * IMPORTANT:
     *
     * Only show incidents created for
     * the currently logged-in student.
     */

    gr.addQuery(
        "caller_id",
        gs.getUserID()
    );


    gr.orderByDesc("sys_created_on");

    gr.query();


    while (gr.next()) {

        data.total++;


        /*
         * STATE
         */

        var stateValue =
            gr.getValue("state");

        var stateText =
            gr.getDisplayValue("state");


        /*
         * ServiceNow incident:
         *
         * 6 = Resolved
         * 7 = Closed
         */

        var isResolved =
            stateValue == "6" ||
            stateValue == "7";


        if (isResolved) {

            data.resolved++;

        } else {

            data.active++;

        }


        /*
         * =====================================
         * PRIORITY
         * =====================================
         */

        var priorityValue =
            gr.getValue("priority");

        var priorityText =
            gr.getDisplayValue("priority");

        var priorityClass =
            "priority-medium";


        if (priorityValue == "1") {

            priorityText = "Critical";

            priorityClass =
                "priority-critical";

        }

        else if (priorityValue == "2") {

            priorityText = "High";

            priorityClass =
                "priority-high";

        }

        else if (priorityValue == "3") {

            priorityText = "Medium";

            priorityClass =
                "priority-medium";

        }

        else if (priorityValue == "4") {

            priorityText = "Low";

            priorityClass =
                "priority-low";

        }


        /*
         * =====================================
         * STATUS CLASS
         * =====================================
         */

        var statusClass =
            isResolved
                ? "status-resolved"
                : "status-active";


        /*
         * =====================================
         * DEFAULT ICON
         * =====================================
         */

        var icon =
            "fa-file-text";

        var iconClass =
            "teal";


        /*
         * =====================================
         * CFMS CUSTOM FIELDS
         * =====================================
         */

        var mealType = "";

        var messHall = "";


        if (gr.isValidField("u_cfms_meal_type")) {

            mealType =
                gr.getDisplayValue(
                    "u_cfms_meal_type"
                );

        }


        if (gr.isValidField("u_cfms_mess_hall")) {

            messHall =
                gr.getDisplayValue(
                    "u_cfms_mess_hall"
                );

        }


        /*
         * =====================================
         * REQUEST OBJECT
         * =====================================
         */

        data.requests.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getValue("number"),

            short_description:
                gr.getValue(
                    "short_description"
                ),

            state:
                stateText,

            stateValue:
                stateValue,

            statusClass:
                statusClass,

            priority:
                priorityText,

            priorityValue:
                priorityValue,

            priorityClass:
                priorityClass,

            created:
                gr.getDisplayValue(
                    "sys_created_on"
                ),

            mealType:
                mealType || "Food Service",

            messHall:
                messHall || "Campus Mess",

            icon:
                icon,

            iconClass:
                iconClass

        });

    }

})();
